// Stage-1 seam helper (safe-state migration): optional `gentity_t*` handles are
// `Option<EntityId>`; resolve one back to the live raw pointer the still-verbatim
// function bodies deref. NULL-preserving (`None` -> null pointer), so a body's
// verbatim `x.is_null()` check keeps its exact meaning. Deref-saturated fns
// re-derive their `EntityId`/`Option<EntityId>` params at the top of the body
// (this + `ctx.entity_mut(id)`) and are otherwise kept verbatim — Stage-2 body
// debt, same recipe as `g_trigger.rs`.
#[inline]
unsafe fn ent_resolve_opt(ctx: GameContext<'_>, id: Option<EntityId>) -> *mut gentity_t {
    match id {
        Some(i) => unsafe { &mut (*ctx.world).g_entities[i.index()] as *mut gentity_t },
        None => core::ptr::null_mut(),
    }
}

// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads `g_adaptRespawn`
// (cvar) and `level.numPlayingClients` — no world handle on the staged
// raw-pointer signature.
/// Raven `adjustRespawnTime`.
///
/// Source: `oracle/codemp/game/g_items.c:47-88`
pub fn adjustRespawnTime(
    ctx: GameContext<'_>,
    preRespawnTime: f32,
    itemType: c_int,
    itemTag: c_int,
) -> c_int {
    // Raven `#define RESPAWN_AMMO 40` (`g_items.c:26`).
    pub const RESPAWN_AMMO: f32 = 40.0;
    const IT_WEAPON: c_int = crate::prelude::IT_WEAPON as c_int;
    const WP_THERMAL: c_int = mp_bg::weapons::weapon_t::WP_THERMAL as c_int;
    const WP_TRIP_MINE: c_int = mp_bg::weapons::weapon_t::WP_TRIP_MINE as c_int;
    const WP_DET_PACK: c_int = mp_bg::weapons::weapon_t::WP_DET_PACK as c_int;

    let mut respawnTime = preRespawnTime;

    if itemType == IT_WEAPON
        && (itemTag == WP_THERMAL || itemTag == WP_TRIP_MINE || itemTag == WP_DET_PACK)
    {
        // special case for these, use ammo respawn rate
        respawnTime = RESPAWN_AMMO;
    }

    unsafe {
        if (*ctx.world).cvars.g_adaptRespawn.integer == 0 {
            return respawnTime as c_int;
        }

        let numPlayingClients = (*ctx.world).level.numPlayingClients;
        if numPlayingClients > 4 {
            // Start scaling the respawn times.
            if numPlayingClients > 32 {
                // 1/4 time minimum.
                respawnTime *= 0.25;
            } else if numPlayingClients > 12 {
                // From 12-32, scale from 0.5 to 0.25;
                respawnTime *= 20.0 / (numPlayingClients + 8) as f32;
            } else {
                // From 4-12, scale from 1.0 to 0.5;
                respawnTime *= 8.0 / (numPlayingClients + 4) as f32;
            }
        }
    }

    if respawnTime < 1.0 {
        // No matter what, don't go lower than 1 second, or the pickups become very noisy!
        respawnTime = 1.0;
    }

    respawnTime as c_int
}

// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads `level.time` and
// the file-static `shieldDeactivateSound` — no world handle.
/// Raven `ShieldRemove`.
///
/// Source: `oracle/codemp/game/g_items.c:108-119`
pub fn ShieldRemove(ctx: GameContext<'_>, self_: EntityId) {
    unsafe {
        // Stage-1: `EntityId` signature; body kept verbatim via a re-derived raw
        // pointer (Stage-2 body debt).
        let self_ = ctx.entity_mut(self_) as *mut gentity_t;
        (*self_).think = Some(EntThink::G_FreeEntity).into();
        (*self_).nextthink = (*ctx.world).level.time + 100;

        // Play kill sound...
        G_AddEvent(
            &mut *(self_),
            entity_event_t::EV_GENERAL_SOUND as c_int,
            (*ctx.world).globals.shieldDeactivateSound,
        );
        (*self_).s.loopSound = 0;
        (*self_).s.loopIsSoundset = qfalse;
    }
}

// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads `g_gametype` and
// `level.time` — no world handle.
/// Raven `ShieldThink`.
///
/// Source: `oracle/codemp/game/g_items.c:123-141`
pub fn ShieldThink(ctx: GameContext<'_>, self_: EntityId) {
    // Raven `#define SHIELD_HEALTH_DEC 10` / `SHIELD_SIEGE_HEALTH_DEC (2000/25)` (`g_items.c:92,99`).
    pub const SHIELD_SIEGE_HEALTH_DEC: c_int = 2000 / 25;
    pub const SHIELD_HEALTH_DEC: c_int = 10;

    unsafe {
        // Stage-1: `EntityId` signature; body kept verbatim via a re-derived raw
        // pointer (Stage-2 body debt).
        let self_ = ctx.entity_mut(self_) as *mut gentity_t;
        (*self_).s.trickedentindex = 0;

        if (*ctx.world).cvars.g_gametype.integer == GT_SIEGE {
            (*self_).health -= SHIELD_SIEGE_HEALTH_DEC;
        } else {
            (*self_).health -= SHIELD_HEALTH_DEC;
        }
        (*self_).nextthink = (*ctx.world).level.time + 1000;
        if (*self_).health <= 0 {
            ShieldRemove(ctx, ctx.entity_id_of(self_).unwrap());
        }
    }
}

