// PORT-NOTE(raw-ptr-skeleton-no-world-handle): reads `bg_itemlist`/
// `g_entities` — no world handle.
/// Raven `EWebDie`.
///
/// Source: `oracle/codemp/game/g_items.c:1449-1481`
pub fn EWebDie(
    ctx: GameContext<'_>,
    self_: EntityId,
    inflictor: Option<EntityId>,
    attacker: Option<EntityId>,
    damage: c_int,
    r#mod: c_int,
) {
    // Raven `#define EWEB_DEATH_DMG 90` / `EWEB_DEATH_RADIUS 128` (`g_items.c:1442-1443`).
    pub const EWEB_DEATH_DMG: f32 = 90.0;
    pub const EWEB_DEATH_RADIUS: f32 = 128.0;

    unsafe {
        // Stage-1: handle signature; body kept verbatim via re-derived raw
        // pointers (Stage-2 body debt).
        let self_ = ctx.entity_mut(self_) as *mut gentity_t;
        let inflictor = ent_resolve_opt(ctx, inflictor);
        let attacker = ent_resolve_opt(ctx, attacker);
        G_RadiusDamage(
            ctx,
            (*self_).r.currentOrigin,
            ctx.entity_id_of(self_),
            EWEB_DEATH_DMG,
            EWEB_DEATH_RADIUS,
            ctx.entity_id_of(self_),
            ctx.entity_id_of(self_),
            MOD_SUICIDE as c_int,
        );

        let fxDir: vec3_t = [1.0, 0.0, 0.0];
        G_PlayEffect(
            EFFECT_EXPLOSION_DETPACK as c_int,
            (*self_).r.currentOrigin,
            fxDir,
        );

        if (*self_).r.ownerNum != ENTITYNUM_NONE {
            let owner =
                &mut (*ctx.world).g_entities[(*self_).r.ownerNum as usize] as *mut gentity_t;

            if (*owner).inuse != 0 && !(*owner).client.is_null() {
                EWebDisattach(
                    ctx,
                    ctx.entity_id_of(owner).unwrap(),
                    ctx.entity_id_of(self_).unwrap(),
                );

                // make sure it resets next time we spawn one in case we someone obtain one before death
                (*((*owner).client as *mut gclient_t)).ewebHealth = -1;

                // take it away from him, it is gone forever.
                (*((*owner).client as *mut gclient_t)).ps.stats[STAT_HOLDABLE_ITEMS as usize] &=
                    !(1 << HI_EWEB);

                if (*((*owner).client as *mut gclient_t)).ps.stats[STAT_HOLDABLE_ITEM as usize] > 0
                    && bg_itemlist[(*((*owner).client as *mut gclient_t)).ps.stats
                        [STAT_HOLDABLE_ITEM as usize] as usize]
                        .giType
                        == IT_HOLDABLE
                    && bg_itemlist[(*((*owner).client as *mut gclient_t)).ps.stats
                        [STAT_HOLDABLE_ITEM as usize] as usize]
                        .giTag
                        == HI_EWEB
                {
                    //he has it selected so deselect it and select the first thing available
                    (*((*owner).client as *mut gclient_t)).ps.stats[STAT_HOLDABLE_ITEM as usize] =
                        0;
                    BG_CycleInven(
                        &mut (*((*owner).client as *mut gclient_t)).ps as *mut playerState_t,
                        1,
                    );
                }
            }
        }
    }
}

