// PORT-NOTE(vec3-outparam-seam): resolved `AngleVectors` takes
// `vec3_t` by value, so its `forward`/`right` out-params (used to compute
// the drop velocity) cannot be received.
/// Raven `Drop_Item`.
///
/// Source: `oracle/codemp/game/g_items.c:2742-2755`
pub fn Drop_Item(
    ctx: GameContext<'_>,
    ent: EntityId,
    item: *mut gitem_t,
    angle: f32,
) -> *mut gentity_t {
    unsafe {
        // Stage-1: `EntityId` param (`item` is a `gitem_t*`; the `*mut gentity_t`
        // RETURN keeps its raw shape — returns ride a later pass). Body kept
        // verbatim via a re-derived raw pointer (Stage-2 body debt).
        let ent = ctx.entity_mut(ent) as *mut gentity_t;
        let mut angles = (*ent).s.apos.trBase;
        angles[YAW] += angle;
        angles[PITCH] = 0.0; // always forward

        let mut velocity: vec3_t = [0.0; 3];
        AngleVectors(angles, Some(&mut velocity), None, None);
        velocity[0] *= 150.0;
        velocity[1] *= 150.0;
        velocity[2] *= 150.0;
        velocity[2] += 200.0 + (*ctx.world).bg_state.rng.crandom() * 50.0;

        LaunchItem(ctx, item, (*ent).s.pos.trBase, velocity)
    }
}

